-- P5 中文閱讀 5CR1–5CR5 整批擴充：35 篇文章、350 題
-- 每篇 500–700 字並配 10 題；每單元新增 70 題，由現有 10 題增至 80 題。
-- 可安全重複執行，不刪除原有題目。

begin;

do $$
declare missing_codes text;
begin
  select string_agg(code, ', ' order by code) into missing_codes
  from (values ('5CR1'),('5CR2'),('5CR3'),('5CR4'),('5CR5')) wanted(code)
  where not exists (select 1 from public.curriculum_nodes n where n.code = wanted.code);
  if missing_codes is not null then raise exception '找不到課程單元：%', missing_codes; end if;
end $$;

create temporary table tmp_chinese_reading_expansion (
  node_code text not null, passage_title text not null, question_text text not null,
  options jsonb not null, correct_answer jsonb not null, explanation text not null,
  hint text not null, difficulty integer not null
) on commit drop;

insert into tmp_chinese_reading_expansion
  (node_code, passage_title, question_text, options, correct_answer, explanation, hint, difficulty)
values
  ('5CR1', '會呼吸的菜園', '《會呼吸的菜園》
星期一早上，校園天台比平日安靜。梓晴原本只是按老師安排完成值日，卻意外發現連日炎熱令菜苗枯萎。其他同學圍過來，有人主張立即放棄，有人急着用最快的方法處理，也有人認為事情與自己無關。梓晴沒有立刻下結論，而是把眼前情況記錄下來，再詢問老師和熟悉環境的人。
大家討論後，決定用廢棄膠瓶製作滴灌裝置。第一次嘗試並不順利：工具不合用，分工也有重複。梓晴提議把工作拆成觀察、準備、操作和記錄四部分，每組只負責一項，完成後再互相檢查。過程中，他們發現真正的原因和最初猜想並不完全相同，於是調整方法，沒有因一次失敗便停止。
午息時，幾位原本旁觀的同學也加入。他們先聽清楚安全提醒，再按記錄逐步工作。梓晴特別提醒大家，不要只追求表面上完成，更要留意方法會否帶來新的問題。班主任沒有代替他們作決定，只在需要時提出問題，讓同學自己比較各種方案的好處和限制。
幾天後，菜苗恢復生氣，班級建立澆水輪值表。大家把過程整理成圖文記錄，貼在課室的分享板上。當中既有成功的步驟，也保留了失敗的嘗試，因為梓晴認為，錯誤能提醒後來的人少走彎路。原本只屬於一小組的任務，漸漸成為全班共同關心的事情。
事情結束後，梓晴回望整個過程，明白遇到問題要觀察原因、合作試驗。真正值得記住的，不只是最後的成果，而是大家願意聆聽、分工、修正和承擔。下次再遇上未知的困難，他們也不會只等別人給答案，而會先觀察，再用行動尋找可行的方法。

