午息時，幾位原本旁觀的同學也加入。他們先聽清楚安全提醒，再按記錄逐步工作。皓文特別提醒大家，不要只追求表面上完成，更要留意方法會否帶來新的問題。班主任沒有代替他們作決定，只在需要時提出問題，讓同學自己比較各種方案的好處和限制。
幾天後，在器材室找回樂器，演出順利完成。大家把過程整理成圖文記錄，貼在課室的分享板上。當中既有成功的步驟，也保留了失敗的嘗試，因為皓文認為，錯誤能提醒後來的人少走彎路。原本只屬於一小組的任務，漸漸成為全班共同關心的事情。
事情結束後，皓文回望整個過程，明白遇事保持冷靜並按線索解決問題。真正值得記住的，不只是最後的成果，而是大家願意聆聽、分工、修正和承擔。下次再遇上未知的困難，他們也不會只等別人給答案，而會先觀察，再用行動尋找可行的方法。

