星期一早上，海邊小鎮比平日安靜。芷悠原本只是按老師安排完成值日，卻意外發現暴雨後鐘樓的報時聲消失。其他同學圍過來，有人主張立即放棄，有人急着用最快的方法處理，也有人認為事情與自己無關。芷悠沒有立刻下結論，而是把眼前情況記錄下來，再詢問老師和熟悉環境的人。
大家討論後，決定訪問老居民、整理舊照片並協助師傅檢查鐘機。第一次嘗試並不順利：工具不合用，分工也有重複。芷悠提議把工作拆成觀察、準備、操作和記錄四部分，每組只負責一項，完成後再互相檢查。過程中，他們發現真正的原因和最初猜想並不完全相同，於是調整方法，沒有因一次失敗便停止。
午息時，幾位原本旁觀的同學也加入。他們先聽清楚安全提醒，再按記錄逐步工作。芷悠特別提醒大家，不要只追求表面上完成，更要留意方法會否帶來新的問題。班主任沒有代替他們作決定，只在需要時提出問題，讓同學自己比較各種方案的好處和限制。
幾天後，鐘樓重新報時，學生製成社區歷史展板。大家把過程整理成圖文記錄，貼在課室的分享板上。當中既有成功的步驟，也保留了失敗的嘗試，因為芷悠認為，錯誤能提醒後來的人少走彎路。原本只屬於一小組的任務，漸漸成為全班共同關心的事情。
事情結束後，芷悠回望整個過程，明白保護舊物也在保存共同記憶。真正值得記住的，不只是最後的成果，而是大家願意聆聽、分工、修正和承擔。下次再遇上未知的困難，他們也不會只等別人給答案，而會先觀察，再用行動尋找可行的方法。

