  ('5CR2', '城市樹木的降溫本領', '《城市樹木的降溫本領》
城市樹木看似是日常生活中普通的一部分，背後卻有不少值得了解的科學和環境知識。它的重要特點是樹冠遮擋陽光，葉片蒸散水分。研究人員不會只憑一次觀察下結論，而會在不同時間和地點收集資料，再比較天氣、季節及人類活動帶來的變化。
目前最需要關注的問題是硬地吸熱和樹木不足令街道升溫。這些影響往往不是立即出現，有時會經過一段時間才被察覺。如果只處理表面現象，而忽略源頭，短期內雖然看似改善，問題仍可能再次發生。因此，了解各因素之間的關係，比單看一個數字更可靠。
可行的改善方法包括增加合適樹種、保留泥土空間並定期護理。個人、學校、社區和政府各有不同角色：個人可改變日常習慣，學校可進行教育和記錄，社區可協調設施，專業部門則負責長期規劃。只有各方面互相配合，措施才不會停留在口號。
不過，樹木需多年成長，規劃不能只求快速。評估成效時，應先訂出清楚目標，再持續記錄。例如比較措施前後的數量、範圍或變化速度，也要留意其他同時出現的因素。資料若只來自單一日子或單一地點，便未必能代表整體情況。
認識城市樹木的最終目的，不只是記住幾個名詞，而是明白改善微氣候並提供生物棲息地。當人們能根據證據作出選擇，便較少被片面說法影響。環境問題通常沒有一個立刻見效的簡單答案，但每項經過思考和持續實行的措施，都能累積成真正的改變。

問題：文章指出需要面對的問題或顧慮是甚麼？', '[{"id":"a","text":"硬地吸熱和樹木不足令街道升溫"},{"id":"b","text":"增加合適樹種、保留泥土空間並定期護理"},{"id":"c","text":"改善微氣候並提供生物棲息地"},{"id":"d","text":"參加者人數太少"}]'::jsonb, '"a"'::jsonb, '根據文章內容，答案是「硬地吸熱和樹木不足令街道升溫」。', '細閱全文，找出相關線索後再比較選項。', 4),
