目前最需要關注的問題是進入河流海洋後可能被生物誤食。這些影響往往不是立即出現，有時會經過一段時間才被察覺。如果只處理表面現象，而忽略源頭，短期內雖然看似改善，問題仍可能再次發生。因此，了解各因素之間的關係，比單看一個數字更可靠。
可行的改善方法包括減少即棄塑膠、妥善分類和選用耐用物品。個人、學校、社區和政府各有不同角色：個人可改變日常習慣，學校可進行教育和記錄，社區可協調設施，專業部門則負責長期規劃。只有各方面互相配合，措施才不會停留在口號。
不過，單靠清理海面不能移除所有微粒。評估成效時，應先訂出清楚目標，再持續記錄。例如比較措施前後的數量、範圍或變化速度，也要留意其他同時出現的因素。資料若只來自單一日子或單一地點，便未必能代表整體情況。
認識微塑膠的最終目的，不只是記住幾個名詞，而是明白從源頭減少塑膠污染。當人們能根據證據作出選擇，便較少被片面說法影響。環境問題通常沒有一個立刻見效的簡單答案，但每項經過思考和持續實行的措施，都能累積成真正的改變。

