珊瑚礁看似是日常生活中普通的一部分，背後卻有不少值得了解的科學和環境知識。它的重要特點是由細小珊瑚蟲群體形成，為海洋生物提供家園。研究人員不會只憑一次觀察下結論，而會在不同時間和地點收集資料，再比較天氣、季節及人類活動帶來的變化。
