可行的改善方法包括減少污水、設立保護區和負責任地潛水。個人、學校、社區和政府各有不同角色：個人可改變日常習慣，學校可進行教育和記錄，社區可協調設施，專業部門則負責長期規劃。只有各方面互相配合，措施才不會停留在口號。
不過，珊瑚生長緩慢，破壞後難以迅速恢復。評估成效時，應先訂出清楚目標，再持續記錄。例如比較措施前後的數量、範圍或變化速度，也要留意其他同時出現的因素。資料若只來自單一日子或單一地點，便未必能代表整體情況。
認識珊瑚礁的最終目的，不只是記住幾個名詞，而是明白維持海洋生物多樣性。當人們能根據證據作出選擇，便較少被片面說法影響。環境問題通常沒有一個立刻見效的簡單答案，但每項經過思考和持續實行的措施，都能累積成真正的改變。

