不過，本地食物不一定在所有情況下碳排放最低。評估成效時，應先訂出清楚目標，再持續記錄。例如比較措施前後的數量、範圍或變化速度，也要留意其他同時出現的因素。資料若只來自單一日子或單一地點，便未必能代表整體情況。
認識食物里程的最終目的，不只是記住幾個名詞，而是明白作出有根據而不簡化的環保選擇。當人們能根據證據作出選擇，便較少被片面說法影響。環境問題通常沒有一個立刻見效的簡單答案，但每項經過思考和持續實行的措施，都能累積成真正的改變。

