為鼓勵居民從生活中學習並服務社區，主辦單位將於一月十日至二月七日逢星期六下午二時至四時在城市歷史館舉行「小小導賞員培訓」。活動費用全免，但參加者必須預先登記；名額有限，主辦單位會按完成登記的先後次序確認資格。成功報名者將於活動前三天收到確認電郵和集合位置。
參加者應帶備筆記簿、鉛筆及一分鐘自我介紹。為保障安全和減少廢物，場內不接受食物、飲品和大型行李。所有個人物品須自行保管，主辦單位不會提供寄存服務。參加者宜穿着輕便服裝，並在活動開始前十五分鐘到達，以便點名及聽取安全講解。
報名截止日期為十二月二十日前提交申請。如需取消，應最遲於活動前三天通知，以便候補人士參加。活動重點包括：四節全勤並通過講解練習才獲證書。導師會先作示範，參加者必須聽從指示，不可自行離隊，也不可在未獲准許下觸碰工具、生物或展品。
特別注意：只接受小五及小六學生。如活動當日上午八時仍懸掛八號熱帶氣旋警告、紅色或黑色暴雨警告，活動將會取消，並以電郵通知；其他天氣情況則由主辦單位按現場安全決定。已取消的活動不設即日改期，新的安排會稍後公布。
場地設有飲水處和基本急救用品。如有食物敏感、行動需要或其他健康情況，請在報名表中註明。參加者完成活動後會收到電子問卷，意見將用作改善日後安排。主辦單位希望大家不但享受活動，也能把所學帶回家庭和社區，讓一次參與延續成日常習慣。

