它可能成為一盞燈、一滴水，
也可能只是有人回頭時的一個微笑。
當我們願意停步細看，
便會明白尊重在夜間工作的人。

明天，深夜巴士還會再次醒來，
帶着未寫完的故事繼續前行。
而我會把今天收進心裏，
不讓忙碌抹去感謝，
也不讓告別成為真正的遺忘。
因為每一次凝望和守候，
都在為平凡日子添上一行溫柔的詩。

