清早，深夜巴士從薄霧裏醒來，
先把一線微光放在窗沿，
再把黃色車燈、濕亮路面、安靜乘客，
一件一件，交給尚未完全甦醒的街道。
我站在轉角，沒有催促，
只聽見時間用很輕的腳步走近。

中午，人群像潮水來去，
每張臉都帶着自己的方向。
有人匆忙，有人停下，
有人把一句問候留給陌生人。
深夜巴士沒有說話，卻把細小變化記住，
讓普通的一天也有可以珍藏的光。

風來時，舊日的聲音被翻開，
一頁是笑聲，一頁是沉默，
還有那些來不及說出的謝意。
我以手掌接住片刻的溫度，
才發現城市裏的默默服務和深夜仍亮着的責任，
從來不需要響亮的名字。

黃昏把影子慢慢拉長，
深夜巴士沿着由總站出發到黎明前回程，穿過仍未入睡的大街小巷，
經過熟悉又陌生的景物。
昨日留下的痕跡沒有消失，
只是藏進牆角、泥土和人的記憶，
等待下一次相遇時重新發亮。

夜色降下來，我仍願意相信，
微小的善意不會白白離去。
它可能成為一盞燈、一滴水，
也可能只是有人回頭時的一個微笑。
當我們願意停步細看，
便會明白尊重在夜間工作的人。

明天，深夜巴士還會再次醒來，
帶着未寫完的故事繼續前行。
而我會把今天收進心裏，
不讓忙碌抹去感謝，
也不讓告別成為真正的遺忘。
因為每一次凝望和守候，
都在為平凡日子添上一行溫柔的詩。

