問題：哪一個標題最適合本文？', '[{"id":"a","text":"《一次普通的午睡》"},{"id":"b","text":"《沒有人的地方》"},{"id":"c","text":"《最快的遊戲》"},{"id":"d","text":"《功課也需要選擇》"}]'::jsonb, '"d"'::jsonb, '根據文章內容，答案是「《功課也需要選擇》」。', '細閱全文，找出相關線索後再比較選項。', 2),
  ('5CR5', '社區需要更多可坐的地方', '《社區需要更多可坐的地方》
學校和社區每天都要作出不少選擇。有些安排沿用多年，看似方便，卻未必能照顧現時的需要。我主張在步行路線設置有遮蔭的座椅。這並不是為了追求新奇，而是希望用較合適的方法解決實際問題。
支持這項建議的主要理由是：長者、幼童和行動不便者可中途休息。當一項安排讓參與者容易理解、願意實行，效果才可能持續。若只靠一次宣傳或少數人的熱心，活動結束後往往便回到原狀。因此，制度既要有清楚目標，也要讓使用者感到自己能夠參與。
反對者提出，有人擔心座椅會阻塞通道或聚集噪音。這項憂慮並非毫無道理，任何改變都可能增加工作或帶來意料之外的情況。可是，因為有困難便完全不嘗試，也會失去改善的機會。比較合理的做法，是先訂出範圍和期限，小規模試行，再以資料判斷。
具體而言，我建議先檢查通道闊度並在合適位置試設。試行期間可記錄參與人數、實際需要、出現的問題和使用者意見。若效果不理想，便調整方法；若證明有效，再逐步擴大。這樣既不會一次投入過多資源，也能避免只憑個別印象作決定。
最重要的是，友善城市應照顧不同人的步行能力。好的安排不一定令所有人做相同的事，而是讓不同需要得到合理照顧，同時不妨礙別人。只要願意聆聽、以證據檢討並共同承擔，改變便不是額外負擔，而會成為學習如何建設更友善環境的機會。

