  ('5CR5', '小學生也可以參與社區決策', '《小學生也可以參與社區決策》
學校和社區每天都要作出不少選擇。有些安排沿用多年，看似方便，卻未必能照顧現時的需要。我主張定期舉行兒童意見會並公布回應。這並不是為了追求新奇，而是希望用較合適的方法解決實際問題。
支持這項建議的主要理由是：兒童是設施使用者，能提出成人忽略的需要。當一項安排讓參與者容易理解、願意實行，效果才可能持續。若只靠一次宣傳或少數人的熱心，活動結束後往往便回到原狀。因此，制度既要有清楚目標，也要讓使用者感到自己能夠參與。
反對者提出，有人質疑兒童未必了解成本和限制。這項憂慮並非毫無道理，任何改變都可能增加工作或帶來意料之外的情況。可是，因為有困難便完全不嘗試，也會失去改善的機會。比較合理的做法，是先訂出範圍和期限，小規模試行，再以資料判斷。
具體而言，我建議先提供資料，再由兒童提出有理由的建議。試行期間可記錄參與人數、實際需要、出現的問題和使用者意見。若效果不理想，便調整方法；若證明有效，再逐步擴大。這樣既不會一次投入過多資源，也能避免只憑個別印象作決定。
最重要的是，參與不是任意決定，而是學習負責任地表達。好的安排不一定令所有人做相同的事，而是讓不同需要得到合理照顧，同時不妨礙別人。只要願意聆聽、以證據檢討並共同承擔，改變便不是額外負擔，而會成為學習如何建設更友善環境的機會。

