問題：哪一個標題最適合本文？', '[{"id":"a","text":"《一次普通的午睡》"},{"id":"b","text":"《沒有人的地方》"},{"id":"c","text":"《最快的遊戲》"},{"id":"d","text":"《維修比立即購買更有價值》"}]'::jsonb, '"d"'::jsonb, '根據文章內容，答案是「《維修比立即購買更有價值》」。', '細閱全文，找出相關線索後再比較選項。', 2);

do $$
declare bad_count integer;
begin
  select count(*) into bad_count
  from (values ('5CR1',70),('5CR2',70),('5CR3',70),('5CR4',70),('5CR5',70)) expected(code, qty)
  where (select count(*) from tmp_chinese_reading_expansion t where t.node_code=expected.code) <> expected.qty;
  if bad_count > 0 then raise exception '各單元增補題數檢查失敗。'; end if;
  if (select count(*) from tmp_chinese_reading_expansion) <> 350 then raise exception '總題數不是 350 題。'; end if;
  if exists (
    select 1 from tmp_chinese_reading_expansion
    group by node_code, passage_title having count(*) <> 10
  ) then raise exception '每篇文章必須剛好有 10 題。'; end if;
end $$;

insert into public.questions (node_id, question_type, question_text, options, difficulty, source_type, status)
select n.id, 'multiple_choice', t.question_text, t.options, t.difficulty, 'teacher', 'published'
from tmp_chinese_reading_expansion t
join public.curriculum_nodes n on n.code=t.node_code
where not exists (
  select 1 from public.questions q where q.node_id=n.id and q.question_text=t.question_text
);

insert into public.question_answer_keys (question_id, correct_answer, explanation, hint)
select q.id, t.correct_answer, t.explanation, t.hint
from tmp_chinese_reading_expansion t
join public.curriculum_nodes n on n.code=t.node_code
join public.questions q on q.node_id=n.id and q.question_text=t.question_text
on conflict (question_id) do update set
  correct_answer=excluded.correct_answer, explanation=excluded.explanation, hint=excluded.hint;

commit;

select n.code, n.title_zh,
  count(q.id) filter (where q.status='published') as published_questions
from public.curriculum_nodes n
left join public.questions q on q.node_id=n.id
where n.code in ('5CR1','5CR2','5CR3','5CR4','5CR5')
group by n.code,n.title_zh order by n.code;
